args.sparql:
SELECT ?director ?directorLabel WHERE {
  dbr:Sea_Sorrow dbo:director ?director .
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(lang(?directorLabel) = 'en') }
}

SELECT ?parent ?parentLabel WHERE {
  dbr:Vanessa_Redgrave dbo:parent ?parent .
  OPTIONAL { ?parent rdfs:label ?parentLabel FILTER(lang(?parentLabel) = 'en') }
}

SELECT ?occ ?occLabel WHERE {
  dbr:Rachel_Kempson dbo:occupation ?occ .
  OPTIONAL { ?occ rdfs:label ?occLabel FILTER(lang(?occLabel) = 'en') }
}

SELECT ?mother ?motherLabel WHERE {
  dbr:Sea_Sorrow dbo:director ?director .
  ?director dbo:parent ?mother .
  OPTIONAL { ?mother rdfs:label ?motherLabel FILTER(lang(?motherLabel) = 'en') }
  ?mother dbp:occupation ?occ .
  FILTER(?occ = "Actress"@en)
}

